-                           const cs_lnum_t  icetsm[],
-                           int              itypsm[],
-                           cs_real_t        smacel[],
-                           cs_real_t        viscf[],
-                           cs_real_t        viscb[]);
-
 /*============================================================================
  * Private function definitions
  *============================================================================*/
@@ -869,8 +830,8 @@ cs_solve_equation_scalar(cs_field_t        *f,
                          int                iterns,
                          int                itspdv,
                          const cs_lnum_t    icetsm[],
-                         int                itypsm[],
-                         cs_real_t          smacel[],
+                         int                itypsm_sc[],
