                          cs_real_t          viscf[],
                          cs_real_t          viscb[])
 {
@@ -976,19 +937,6 @@ cs_solve_equation_scalar(cs_field_t        *f,
   else
     cs_gui_thermal_source_terms(f, cvar_var, rhs, fimp);

-  {
-    int nvar = 0, nscal = 0;
-    cs_lnum_t ncepdp = 0;
-    cs_lnum_t *icepdc = NULL;
-    cs_real_t *ckupdc = NULL;
-
-    cs_f_get_dimens(&nvar, & nscal);
-
